import assert from'node:assert/strict';import fs from'node:fs';import crypto from'node:crypto';import{render,sample,overlapCases,specs}from'./clock-v17.mjs';import{render as old}from'../v16/clock-v16.mjs';const norm=s=>s.replace(/v6-\d+/g,'ID'),groups=(s,k)=>[...s.matchAll(new RegExp(`<g data-${k}="[^"\\n]+"[\\s\\S]*?<\\/g>`,'g'))].map(m=>norm(m[0]));let count=0;
for(const variant of['A','B','C'])for(let end=1;end<=12;end++)for(const c of overlapCases)for(const growth of[0,50,100]){const st={...sample,...c.state,end,firstGrowth:growth,secondGrowth:100-growth},s=render(st,{variant}),b=old(st);for(const type of['hand','growth-number','end-number','growth-ticks']){assert.ok(groups(s,type).length);assert.deepEqual(groups(s,type),groups(b,type));}for(const m of s.matchAll(/data-main-number="(\d+)"><text([^>]*)>/g)){const x=+m[2].match(/ x="([^"]+)/)[1],y=+m[2].match(/ y="([^"]+)/)[1],a=+m[1]*Math.PI/6;assert.ok(Math.abs((x-512)*Math.cos(a)+(y-500)*Math.sin(a))<1e-8);assert.ok(m[2].includes('font-size="52"'));}const ticks=[...s.match(/<g data-main-ticks="60">([\s\S]*?)<\/g>/)[1].matchAll(/<line data-tick="(\d+)" x1="([^"]+)" y1="([^"]+)" x2="([^"]+)" y2="([^"]+)"/g)];assert.equal(ticks.length,60);for(const m of ticks){const a=+m[1]*Math.PI/30;for(const i of[2,4])assert.ok(Math.abs((+m[i]-512)*Math.cos(a)+(+m[i+1]-500)*Math.sin(a))<1e-8);}assert.ok(s.includes('data-ring-centerline="true" cx="512" cy="500" r="347"'));assert.ok(s.includes('data-bezel-width="40"'));count++;}
for(const v of['V16','A','B','C']){const s=fs.readFileSync(new URL(`evidence/${v}-stand.svg`,import.meta.url),'utf8'),b=Buffer.from(s.match(/data:image\/jpeg;base64,([^"]+)/)[1],'base64');assert.deepEqual(b,fs.readFileSync(new URL(`evidence/${v}-full.jpg`,import.meta.url)));}const rows=JSON.parse(fs.readFileSync(new URL('evidence/clearance.json',import.meta.url))).rows;for(const v of['B','C'])for(const r of rows.filter(r=>r.variant===v))assert.ok(Math.min(r.silver,r.ticks,r.bezel)>=8,JSON.stringify(r));console.log({count,main52:true,axis30:true,bezel40:true,ring347:true,handsSubdialsUnchanged:true,standBytesIdentical:true,BCclearanceAtLeast8:true});
